        return 0;
    }

    int maxLength = 0;
    for (int i = 0; i < strings.size(); i++) {
        int currentLength = strings.size();
        String currentString = strings.get(i);
        for (int j = 0; j < currentString.length(); j++) {
            String substr = currentString.substring(j);
            int index = strings.indexOf(substr);
            if (index != -1 && index != 0) {
                currentString = currentString.substring(0, j) + currentString.substring(j + substr.length());
                currentLength++;
            }
            if (currentLength > maxLength) {
                maxLength = currentLength;
            }
        }
    }

    return maxLength - 1; // Subtract 1 to exclude the full string
}

