public String sortString(String s) {
        if (s == null || s.length() <= 1) {
            return s;
        }

        Deque<Character> maxQueue = new PriorityQueue<>((a, b) -> b - a);
        Deque<Character> minQueue = new PriorityQueue<>();
        boolean[] seen = new boolean[256];

        for (char c : s.toCharArray()) {
            if (seen[c]) {
                maxQueue.offer(c);
                minQueue.offer(c);
            } else {
                seen[c] = true;
            }
        }

        String result = new StringBuilder();

        while (!maxQueue.isEmpty() || !minQueue.isEmpty()) {
            // Append the smaller character to the result and remove from the queue
            if (!maxQueue.isEmpty() && (!minQueue.isEmpty() || maxQueue.peek() >= minQueue.peek())) {
                char top = maxQueue.poll();
                result.append(top);
                seen[top] = false;
            }

            // Append the larger character to the result and remove from the queue
            if (!minQueue.isEmpty()) {
                char top = minQueue.poll();
                result.append(top);
                seen[top] = false;
            }
        }

        return result.toString();
    }

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the total sum of the array
    int totalSum = Arrays.stream(nums).sum();

    // If the total sum is odd, it's impossible to split the array into two equal averages
    if (totalSum % 2 != 0) {
        return false;
    }

    // Calculate the target sum for one of the partitions
    int targetSum = totalSum / 2;

    // Check if there exists a prefix sum that equals the target sum
    int prefixSum = 0;
    for (int num : nums) {
        prefixSum += num;
        if (prefixSum == targetSum) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
        if (cost == null || cost.length < 2) {
            return cost.length == 0 ? 0 : cost[0];
        }

        int[] dp = new int[cost.length];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = cost[0];
        dp[1] = cost[1];

        for (int i = 2; i < cost.length; i++) {
            dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
        }

        return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
    }

