public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Check horizontally
    for (int i = 0; i < m; i++) {
        int currentLength = 1;
        for (int j = 1; j < n; j++) {
            if (mat[i][j] == mat[i][j - 1]) {
                currentLength++;
                maxLength = Math.max(maxLength, currentLength);
            } else {
                currentLength = 1;
            }
        }
    }

    // Check vertically
    for (int j = 0; j < n; j++) {
        int currentLength = 1;
        for (int i = 1; i < m; i++) {
            if (mat[i][j] == mat[i - 1][j]) {
                currentLength++;
                maxLength = Math.max(maxLength, currentLength);
            } else {
                currentLength = 1;
            }
        }
    }

    // Check diagonally (75 degrees)
    for (int i = 0; i < m; i++) {
        int j = 0;
        int currentLength = 1;
        while (i < m && j < n && mat[i][j] == mat[i + 1][j + 1]) {
            currentLength++;
            maxLength = Math.max(maxLength, currentLength);
            i++;
            j++;
        }
    }

    // Check anti-diagonally (315 degrees)
    for (int i = 0; i < m; i++) {
        int j = n - 1;
        int currentLength = 1;
        while (i < m && j >= 0 && mat[i][j] == mat[i + 1][j - 1]) {
            currentLength++;
            maxLength = Math.max(maxLength, currentLength);
            i++;
            j--;
        }
    }

    return maxLength;
}

