public int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    Deque<Integer> stack = new ArrayDeque<>();

    for (int i = 0; i <= heights.length; i++) {
        int height = (i == heights.length) ? 0 : heights[i];

        while (!stack.isEmpty() && height < heights[stack.peek()]) {
            int top = stack.pop();
            int width;
            if (stack.isEmpty()) {
                width = i;
            } else {
                width = i - stack.peek() - 1;
            }
            int area = width * heights[top];
            maxArea = Math.max(maxArea, area);
        }
        stack.push(i);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int top = 0, bottom = mat.length - 1, left = 0, right = mat[0].length - 1;
    int[] result = new int[mat.length * mat[0].length];
    int count = 0;

    while (top <= bottom && left <= right) {
        for (int i = left; i <= right; i++) {
            result[count++] = mat[top][i];
        }
        top++;

        for (int i = top; i <= bottom; i++) {
            result[count++] = mat[i][right];
        }
        right--;

        if (top <= bottom) {
            for (int i = right; i >= left; i--) {
                result[count++] = mat[bottom][i];
            }
            bottom--;
        }

        if (left <= right) {
            for (int i = bottom; i >= top; i--) {
                result[count++] = mat[i][left];
            }
            left++;
        }
    }

    return result;
}

