    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

        // Calculate the slopes of the two lines AB and BC
        double a = (y2 - y1) / (x2 - x1);
        double b = (y3 - y2) / (x3 - x2);

        // If the slopes are different and both are not infinity or -infinity,
        // then the points form a boomerang
